/// FnFreeRect (C4Script.cpp:3125-3131): clears the landscape rect in
/// GLOBAL coordinates (no caller offset, unlike DigFree*) without
/// producing dug-out material. The density-filtered form
/// (iFreeDensity -> ClearRectDensity) clears everything in the column
/// model (PORT_STATUS).
/// FnScriptGo (C4Script.cpp:2782-2786): switches the scenario script
/// counter gate (Game.Script.Go) that drives the timed Script%d
/// sections (C4GameScriptHost::Execute, C4ScriptHost.cpp:222-232).
fn script_go(args: &[Value]) -> Result<Value, RuntimeError> {
    let go = match args.first() {
        Some(Value::Bool(flag)) => *flag,
        Some(Value::Int(value)) => *value != 0,
        _ => false,
    };
    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(true));
        };
        context.script_go_request = Some(go);
        Ok(Value::Bool(true))
    })
}

/// FnScriptCounter (C4Script.cpp:3616-3619): zero-argument getter for the
/// live scenario counter. C4GameScriptHost::Execute has already incremented
/// it before entering ScriptN (C4ScriptHost.cpp:222-232), and a preceding
/// goto() in this same VM call is immediately visible.
fn script_counter(_args: &[Value]) -> Result<Value, RuntimeError> {
    HOST_CONTEXT.with(|cell| {
        let borrow = cell.borrow();
        let Some(context) = borrow.as_ref() else {
            return Ok(Value::Int(0));
        };
        Ok(Value::Int(
            context
                .script_counter_request
                .unwrap_or(context.scenario_script_counter),
        ))
    })
}

/// Fn_goto (C4Script.cpp:225-229): synchronously replaces
/// `Game.Script.Counter` and returns the assigned integer. The current
/// C4GameScriptHost pulse has already post-incremented the counter before it
/// calls Script%d (C4ScriptHost.cpp:222-232), so this redirects the next pulse.
fn script_goto(args: &[Value]) -> Result<Value, RuntimeError> {
    let counter = value_to_i32(
        args.first().unwrap_or(&Value::Nil),
        "goto",
        "counter",
    )?;
    HOST_CONTEXT.with(|cell| {
        if let Some(context) = cell.borrow_mut().as_mut() {
            context.script_counter_request = Some(counter);
        }
        Ok(Value::Int(counter))
    })
}

/// FnDrawMaterialQuad (C4Script.cpp:5111-5115): all coordinates are GLOBAL
/// (there is no cthr->Obj offset), and the bool is the Surface8 IFT bit.
/// GetIndexMatTex runs synchronously so an unresolved material returns false
/// without queuing a landscape change (C4Landscape.cpp:2448-2452).
fn draw_material_quad(args: &[Value]) -> Result<Value, RuntimeError> {
    let material_texture = parse_optional_string(
        args.first(),
        "DrawMaterialQuad",
        "material-texture",
    )?
    .unwrap_or_default();
    let coordinate_names = ["x1", "y1", "x2", "y2", "x3", "y3", "x4", "y4"];
    let mut coordinates = [0; 8];
    for (index, coordinate) in coordinates.iter_mut().enumerate() {
        *coordinate = value_to_i32(
            args.get(index + 1).unwrap_or(&Value::Nil),
            "DrawMaterialQuad",
            coordinate_names[index],
        )?;
    }
    let ift = value_to_bool(
        args.get(9).unwrap_or(&Value::Nil),
        "DrawMaterialQuad",
        "sub",
    )?;
    let vertices = [
        Vector2::new(coordinates[0], coordinates[1]),
        Vector2::new(coordinates[2], coordinates[3]),
        Vector2::new(coordinates[4], coordinates[5]),
        Vector2::new(coordinates[6], coordinates[7]),
    ];

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Bool(false));
        };
        if !context.resolve_runtime_material_texture(&material_texture) {
            return Ok(Value::Bool(false));
        }
        context.register_landscape_operation(LandscapeOperation::DrawMaterialQuad {
            material_texture,
            vertices,
            ift,
        });
        Ok(Value::Bool(true))
    })
}

/// FnDrawMap/C4Landscape::DrawMap (C4Script.cpp:4851-4855;
/// C4Landscape.cpp:2636-2668): clip the GLOBAL destination first, then make
/// an exact-size temporary S2 map through the callback's live synced RNG.
/// The resulting indexed bytes are queued verbatim so the later engine fold
/// cannot consume the map's size/range/seed draws a second time.
fn draw_map(args: &[Value]) -> Result<Value, RuntimeError> {
    let x = value_to_i32(args.first().unwrap_or(&Value::Nil), "DrawMap", "x")?;
    let y = value_to_i32(args.get(1).unwrap_or(&Value::Nil), "DrawMap", "y")?;
    let width = value_to_i32(args.get(2).unwrap_or(&Value::Nil), "DrawMap", "wdt")?;
    let height = value_to_i32(args.get(3).unwrap_or(&Value::Nil), "DrawMap", "hgt")?;
    let Some(source) = parse_optional_string(args.get(4), "DrawMap", "map-definition")? else {
        return Ok(Value::Int(0));
    };

    HOST_CONTEXT.with(|cell| {
        let mut borrow = cell.borrow_mut();
        let Some(context) = borrow.as_mut() else {
            return Ok(Value::Int(0));
        };
        let Some((landscape_width, landscape_height, map_zoom, retained_creator)) = context
            .world
            .landscape_ref()
            .and_then(|landscape| {
                let (landscape_width, landscape_height) = landscape.grid_dimensions()?;
                let raster = landscape.raster_state()?;
                Some((
                    landscape_width,
                    landscape_height,
                    raster.map_zoom(),
                    raster.map_creator().cloned(),
                ))
            })
        else {
            return Ok(Value::Int(0));
        };
        if map_zoom <= 0 {
            return Ok(Value::Int(0));
        }

        // C4Landscape::ClipRect (C4Landscape.cpp:2698-2707) is the half-open
        // intersection with the landscape. i64 intermediates retain those
        // semantics without overflowing on hostile script integers.
        let left = i64::from(x).max(0);
        let top = i64::from(y).max(0);
        let right = (i64::from(x) + i64::from(width)).min(i64::from(landscape_width));
        let bottom = (i64::from(y) + i64::from(height)).min(i64::from(landscape_height));
        if right <= left || bottom <= top {
            return Ok(Value::Int(0));
        }
        let clipped_x = left as i32;
        let clipped_y = top as i32;
        let clipped_width = (right - left) as i32;
        let clipped_height = (bottom - top) as i32;
        let map_width = (clipped_width - 1) / map_zoom + 1;
        let map_height = (clipped_height - 1) / map_zoom + 1;

        let Some(texmap) = context.runtime_texmap.take() else {
            return Ok(Value::Int(0));
        };
        let texmap_before = texmap.clone();
        let mut classifier = crate::scenario::MapPixelClassifier::from_runtime_state(texmap);
        let rendered = RANDOM_CONTEXT.with(|random_cell| {
            let random_context = random_cell
                .borrow()
                .as_ref()
                .cloned()
                .ok_or_else(|| RuntimeError::new("DrawMap: random context unavailable"))?;
            let mut rng = random_context.rng.borrow_mut();
            Ok(crate::map_creator_s2::render_runtime_s2_map(
                retained_creator.as_ref(),
                &source,
                &mut classifier,
                map_width,
                map_height,
                &mut rng,
            ))
        });
        let texmap = classifier.into_runtime_state();
        // Parser-side texture allocations are live to later calls in this
        // VM session even if Render found no map.
        context.runtime_texmap = Some(texmap.clone());
        let Some(bitmap) = rendered? else {
            if texmap != texmap_before {
                context.register_landscape_operation(LandscapeOperation::SyncRuntimeTexMap {
                    texmap,
                });
            }
            return Ok(Value::Int(0));
        };
        context.register_landscape_operation(LandscapeOperation::DrawMap {
            origin: Vector2::new(clipped_x, clipped_y),
            bitmap,
            map_width,
            map_height,
            texmap,
        });
        Ok(Value::Int(1))
    })
}

