    #[test]
    fn place_animal_invalid_modes_draw_nothing_and_air_row_zero_draws_once() {
        // C4Id2Def and unsupported Placement return before Random; the Air
        // arm draws x, then fails without Random(y) when row zero is already
        // semi-solid (C4Game.cpp:3028-3061).
        let mut landscape = Landscape::flat(20, 0);
        landscape.set_world_height(20);
        let definitions = HashMap::from([
            (
                DefinitionId::from("UNSP"),
                DefinitionMetadata {
                    placement: 9,
                    ..DefinitionMetadata::default()
                },
            ),
            (
                DefinitionId::from("AIR0"),
                DefinitionMetadata {
                    placement: 2,
                    shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                    ..DefinitionMetadata::default()
                },
            ),
            (
                DefinitionId::from("SURF0"),
                DefinitionMetadata {
                    placement: 0,
                    shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                    ..DefinitionMetadata::default()
                },
            ),
        ]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        );
        let mut expected_rng = LcgRng::new(41);
        let _ = expected_rng.random(20);
        let _ = expected_rng.random(20);
        let _ = expected_rng.random(20);
        let expected_after = expected_rng.random(1_000);
        let guard = enter_random_context(LcgRng::new(41));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            Ok::<_, RuntimeError>(Value::Array(vec![
                place_animal(&[Value::C4Id("NONE".into())])?,
                place_animal(&[Value::C4Id("UNSP".into())])?,
                place_animal(&[Value::C4Id("AIR0".into())])?,
                place_animal(&[Value::C4Id("SURF0".into())])?,
                random(&[Value::Int(1_000)])?,
            ]))
        });
        let final_rng = guard.finish();

        assert_eq!(final_rng, expected_rng);
        assert_eq!(
            result.expect("PlaceAnimal failure paths succeed"),
            Value::Array(vec![
                Value::Nil,
                Value::Nil,
                Value::Nil,
                Value::Nil,
                Value::Int(expected_after),
            ])
        );
        assert!(outcome.spawns.is_empty());
    }

    #[test]
    fn place_animal_callbacks_are_synchronous_and_removal_returns_nil() {
        // CreateObject inserts the animal before Construction(nil) at Con=0,
        // then DoCon(FullCon,true) calls Completion and Initialize; removal
        // in Construction makes PlaceAnimal return null while consuming the
        // object number (C4Game.cpp:1102-1146,3028-3061;
        // C4Object.cpp:1428-1515).
        let animal_script = r#"#strict
local iConstructionCon, iConstructionY, iOrder;
protected func Construction() { iConstructionCon=GetCon(); iConstructionY=GetY(); iOrder=1; }
protected func Completion() { iOrder=iOrder*10+2; }
protected func Initialize() { iOrder=iOrder*10+3; }
public func ConstructionCon() { return(iConstructionCon); }
"#;
        let caller_script = r#"#strict
local iObservedCon;
public func Seed() { var child=PlaceAnimal(ANML); iObservedCon=child->ConstructionCon(); return(child); }
public func SeedRemoved() { return(PlaceAnimal(DIEA)); }
"#;
        let mut engine = crate::Engine::with_seed(53);
        let mut landscape = Landscape::flat(100, 60);
        landscape.set_world_height(100);
        engine.set_landscape(landscape);
        let mut animal = crate::Definition::from_script("ANML", "Animal", animal_script)
            .expect("animal script compiles");
        animal.set_category(crate::CATEGORY_LIVING);
        animal.set_shape_rect(Some(DefinitionRect::new(-2, -3, 4, 6)));
        animal.set_placement(2);
        engine.register_definition(animal).expect("animal registers");
        let mut removed = crate::Definition::from_script(
            "DIEA",
            "Removed animal",
            "#strict\nprotected func Construction() { RemoveObject(); }",
        )
        .expect("removed animal script compiles");
        removed.set_category(crate::CATEGORY_LIVING);
        removed.set_shape_rect(Some(DefinitionRect::new(-2, -3, 4, 6)));
        removed.set_placement(2);
        engine.register_definition(removed).expect("removed animal registers");
        let caller = crate::Definition::from_script("CALL", "Caller", caller_script)
            .expect("caller script compiles");
        engine.register_definition(caller).expect("caller registers");
        let caller_id = engine
            .spawn_object(SpawnConfig::new("CALL").with_position(Vector2::new(1_000, 1_000)))
            .expect("caller spawns");
        let caller_index = engine.find_object_index(caller_id).expect("caller exists");

        let value = engine
            .call_object_function(caller_index, "Seed", Vec::new())
            .expect("Seed runs");
        let animal_id = object_id_from_value(&value).expect("Seed returns live animal");
        let animal_index = engine.find_object_index(animal_id).expect("animal exists");
        let animal = &engine.objects[animal_index].state;
        assert_eq!(animal.owner, OWNER_NONE);
        assert_eq!(animal.controller, OWNER_NONE);
        assert_eq!(animal.construction, FULL_CON);
        assert!((0..100).contains(&animal.position.x), "placement is global");
        assert_eq!(animal.local_vars.get("iConstructionCon"), Some(&Value::Int(0)));
        assert_eq!(animal.local_vars.get("iOrder"), Some(&Value::Int(123)));
        assert_eq!(
            animal.local_vars.get("iConstructionY"),
            Some(&Value::Int(animal.position.y + 3)),
            "Construction sees the raw pre-DoCon y"
        );
        let caller_index = engine.find_object_index(caller_id).expect("caller remains");
        assert_eq!(
            engine.objects[caller_index].state.local_vars.get("iObservedCon"),
            Some(&Value::Int(0)),
            "Construction writes are visible before PlaceAnimal returns"
        );

        let before_next_id = engine.capture_state().next_object_id;
        let value = engine
            .call_object_function(caller_index, "SeedRemoved", Vec::new())
            .expect("SeedRemoved runs");
        assert_eq!(value, Value::Nil);
        assert!(engine
            .snapshot()
            .objects
            .iter()
            .all(|object| object.definition_id != "DIEA"));
        assert_eq!(engine.capture_state().next_object_id, before_next_id + 1);
    }

    #[test]
    fn place_vegetation_uses_relative_surface_area_and_raw_growth_like_cpp() {
        // FnPlaceVegetation makes x/y caller-relative (C4Script.cpp:2487-2492),
        // then the surface arm draws x/y, applies AboveSemiSolid, checks Soil,
        // and passes the raw growth value to CreateObjectConstruction with
        // NO_OWNER (C4Game.cpp:2980-3022).
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let materials = MaterialSet::from_resource_library(&library);
        let earth = materials.id_of("Earth").expect("earth material exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        let definitions = HashMap::from([(
            DefinitionId::from("TREE"),
            DefinitionMetadata {
                category: crate::CATEGORY_STATIC_BACK,
                shape: Some(DefinitionRect::new(-20, -28, 40, 56)),
                placement: 0,
                growth: 2,
                stretch_growth: true,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            2,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let caller = HostObjectContext::new(
            ObjectId::new(1),
            None,
            ObjectStatus::Normal,
            100,
            OWNER_NONE,
            Vector2::new(200, 150),
            Vector2::ZERO,
            &[],
            "Idle",
            0,
            0,
            ActionLibrary::default(),
            Direction::Left,
            CommandDirection::Stop,
            0,
            None,
            None,
            &[],
            FULL_CON,
        );
        let mut expected_rng = LcgRng::new(17);
        assert_eq!(expected_rng.random(200), 94);
        assert_eq!(expected_rng.random(200), 2);
        let guard = enter_random_context(LcgRng::new(17));
        let (result, outcome) = with_effect_context(Some(caller), &[], world, 2, || {
            place_vegetation(&[
                Value::C4Id("TREE".into()),
                Value::Int(-100),
                Value::Int(-100),
                Value::Int(200),
                Value::Int(200),
                Value::Int(10),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng, "exactly the x/y draws are consumed");
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(2))
        );
        assert_eq!(outcome.spawns.len(), 1);
        let spawn = &outcome.spawns[0];
        assert_eq!(spawn.definition_id, "TREE");
        assert_eq!(spawn.position, Vector2::new(194, 168));
        assert_eq!(spawn.construction, 10, "growth is FullCon scale, not percent");
        assert_eq!(spawn.owner, OWNER_NONE);
        assert_eq!(spawn.controller, Some(OWNER_NONE));
    }

    #[test]
    fn place_vegetation_runs_construction_before_partial_growth_like_cpp() {
        // NewObject inserts the object, calls Construction at Con=0, then
        // DoCon(iGrowth, true); Completion+Initialize only run when that
        // transition reaches FullCon (C4Game.cpp:1135-1144;
        // C4Object.cpp:1428-1515). FnPlaceVegetation returns that live object.
        let script = r#"#strict
local iConstructionCon, iCompletion, iInitialized, iObservedCon;

protected func Construction()
{
    iConstructionCon = GetCon();
    DoCon(1);
    return(1);
}

protected func Completion()
{
    iCompletion = 1;
    return(1);
}

protected func Initialize()
{
    iInitialized = 1;
    return(1);
}

public func ConstructionCon()
{
    return(iConstructionCon);
}

public func Seed()
{
    var child = PlaceVegetation(TREE, -100, -100, 200, 200, 10);
    iObservedCon = child->ConstructionCon();
    return(child);
}

public func SeedFull()
{
    return(PlaceVegetation(TREE, -100, -100, 200, 200, 100000));
}
"#;
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let mut engine = crate::Engine::with_seed(17);
        engine.configure_materials_from_library(&library);
        let earth = engine
            .materials()
            .id_of("Earth")
            .expect("earth material exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        engine.set_landscape(landscape);

        let mut tree = crate::Definition::from_script("TREE", "Tree", script)
            .expect("tree script compiles");
        tree.set_category(crate::CATEGORY_STATIC_BACK);
        tree.set_shape_rect(Some(DefinitionRect::new(-20, -28, 40, 56)));
        tree.set_placement(0);
        tree.set_growth(2);
        tree.set_stretch_growth(true);
        engine.register_definition(tree).expect("tree registers");
        let caller = engine
            .spawn_object(
                SpawnConfig::new("TREE")
                    .with_position(Vector2::new(200, 160))
                    .with_category(crate::CATEGORY_STATIC_BACK),
            )
            .expect("caller tree spawns");
        let caller_index = engine.find_object_index(caller).expect("caller exists");
        let value = engine
            .call_object_function(caller_index, "Seed", Vec::new())
            .expect("Seed runs");
        let child_id = object_id_from_value(&value).expect("Seed returns child");
        let child_index = engine.find_object_index(child_id).expect("child exists");
        let child = &engine.objects[child_index].state;

        assert_eq!(
            child.construction, 1_010,
            "the initial DoCon adds raw growth after Construction's change"
        );
        assert_eq!(
            child.local_vars.get("iConstructionCon"),
            Some(&Value::Int(0)),
            "Construction observes the pre-growth Con=0 state"
        );
        assert_eq!(child.local_vars.get("iCompletion"), Some(&Value::Nil));
        assert_eq!(child.local_vars.get("iInitialized"), Some(&Value::Nil));
        let caller_index = engine.find_object_index(caller).expect("caller remains");
        assert_eq!(
            engine.objects[caller_index]
                .state
                .local_vars
                .get("iObservedCon"),
            Some(&Value::Int(0)),
            "the Construction write is visible before PlaceVegetation returns"
        );

        let value = engine
            .call_object_function(caller_index, "SeedFull", Vec::new())
            .expect("SeedFull runs");
        let full_child = object_id_from_value(&value).expect("SeedFull returns child");
        let full_index = engine
            .find_object_index(full_child)
            .expect("full child exists");
        let full = &engine.objects[full_index].state;
        assert_eq!(full.construction, FULL_CON);
        assert_eq!(
            full.local_vars.get("iConstructionCon"),
            Some(&Value::Int(0))
        );
        assert_eq!(full.local_vars.get("iCompletion"), Some(&Value::Int(1)));
        assert_eq!(full.local_vars.get("iInitialized"), Some(&Value::Int(1)));
    }

    #[test]
    fn place_vegetation_finds_liquid_bottom_like_cpp() {
        // C4D_Place_Liquid takes one random point, tries FindSurfaceLiquid
        // then FindLiquid, settles via SemiAboveSolid, and creates three
        // pixels into the bottom (C4Game.cpp:3027-3039;
        // C4Landscape.cpp:1860-1915,1772-1796).
        let library = lc_resources::MaterialLibrary::parse(
            r#"
            [Material Rock]
            Name=Rock
            Density=100

            [Material Water]
            Name=Water
            Density=25
            "#,
        )
        .expect("materials parse");
        let materials = MaterialSet::from_resource_library(&library);
        let rock = materials.id_of("Rock").expect("rock exists");
        let water = materials.id_of("Water").expect("water exists");
        let mut landscape = Landscape::flat_with_material(100, 200, Some(rock));
        landscape.set_world_height(300);
        for x in 20..80 {
            for y in 100..200 {
                assert!(landscape.insert_liquid_at(x, y, Some(water)));
            }
        }
        let definitions = HashMap::from([(
            DefinitionId::from("PLNT"),
            DefinitionMetadata {
                shape: Some(DefinitionRect::new(-2, -3, 4, 6)),
                placement: 1,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let mut expected_rng = LcgRng::new(23);
        assert_eq!(expected_rng.random(1), 0);
        assert_eq!(expected_rng.random(1), 0);
        let guard = enter_random_context(LcgRng::new(23));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            place_vegetation(&[
                Value::C4Id("PLNT".into()),
                Value::Int(50),
                Value::Int(120),
                Value::Int(1),
                Value::Int(1),
                Value::Int(500),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng, "the point costs exactly two draws");
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns.len(), 1);
        assert_eq!(outcome.spawns[0].position, Vector2::new(49, 202));
        assert_eq!(outcome.spawns[0].construction, 500);
    }

    #[test]
    fn place_vegetation_default_growth_uses_cpp_random_gate() {
        // iGrowth<=0 first becomes FullCon; a definition with Growth then
        // has a 1-in-3 gate followed by Random(FullCon)+1
        // (C4Game.cpp:2988-2992), before the placement-point draws.
        let library = lc_resources::MaterialLibrary::parse(
            "[Material]\nName=Earth\nDensity=100\nSoil=1\n",
        )
        .expect("earth material parses");
        let materials = MaterialSet::from_resource_library(&library);
        let earth = materials.id_of("Earth").expect("earth exists");
        let mut landscape = Landscape::flat_with_material(400, 160, Some(earth));
        landscape.set_world_height(300);
        let definitions = HashMap::from([(
            DefinitionId::from("TREE"),
            DefinitionMetadata {
                shape: Some(DefinitionRect::new(-20, -28, 40, 56)),
                placement: 0,
                growth: 2,
                stretch_growth: true,
                ..DefinitionMetadata::default()
            },
        )]);
        let world = HostWorldContext::with_landscape(
            Vec::<HostWorldObject>::new(),
            Some(landscape),
            definitions,
            Vec::new(),
            HashMap::new(),
            HashMap::new(),
            1,
            false,
        )
        .with_materials(Some(Rc::new(materials)));
        let mut expected_rng = LcgRng::new(2);
        assert_eq!(expected_rng.random(3), 0);
        let expected_growth = expected_rng.random(FULL_CON) + 1;
        assert_eq!(expected_growth, 29_217);
        assert_eq!(expected_rng.random(1), 0);
        assert_eq!(expected_rng.random(1), 0);
        let guard = enter_random_context(LcgRng::new(2));
        let (result, outcome) = with_effect_context(None, &[], world, 1, || {
            place_vegetation(&[
                Value::C4Id("TREE".into()),
                Value::Int(200),
                Value::Int(50),
                Value::Int(1),
                Value::Int(1),
                Value::Int(0),
            ])
        });
        let rng_after = guard.finish();

        assert_eq!(rng_after, expected_rng);
        assert_eq!(
            result.expect("PlaceVegetation succeeds"),
            object_reference_value(ObjectId::new(1))
        );
        assert_eq!(outcome.spawns[0].construction, expected_growth);
    }

